# %% ../nbs/03_Service.ipynb 7
class Service(Table):
    """
    A Service class of Table for use in generating biobibs and CVs
    """
    def __init__(
            self,
            doc:Doc=None, # Google sheet object
            worksheet:str='Service',   # worksheet name in google sheet
            csv_file:str=None, # optional csv file (if using csv files)
            category:str=None,  # type of service (P = professional, U = university, D = department)
            table_name:str=None, # Will be determined from category.
            cumulative:bool=False, # Is this table cumulative?
            ascending:bool=True, # Sort in ascending order?
            consolidate:bool=False, # Consolidate year ranges for same role?
            template=service_template # template content
    ):
        if not table_name:
            if category not in service_types:
                raise ValueError(f'Category must be one of {service_types.keys}')
            table_name = service_types[category] + ' Service'
            if category is None:
                table_name = 'Service'
        super().__init__(
            doc=doc,
            worksheet=worksheet,
            table_name=table_name,
            csv_file=csv_file,
            template=template)
        self.ascending = ascending
        self.cumulative = cumulative
        self.category = category
        self.consolidate = consolidate
        self.df = self.clean_df()
        print(f'Initialized {self.table_name} table')

# %% ../nbs/03_Service.ipynb 9
@patch
def clean_df(self:Service,
             sort_by:str='Sort Year', # variable to sort by
            )->pd.DataFrame:  # cleaned dataframe
    """
    Clean the Service table.

    """
    print('Cleaning Service Table')
    print('Category:', self.category)

    # Standardize column names to handle different header structures
    df = self.df.copy()

    # Handle duplicate column names (e.g., two 'Year' columns)
    cols = list(df.columns)
    seen = {}
    new_cols = []
    for col in cols:
        if col in seen:
            seen[col] += 1
            new_cols.append(f"{col}_{seen[col]}" if col else f"col_{len(new_cols)}")
        else:
            seen[col] = 0
            new_cols.append(col)
    df.columns = new_cols

    # Rename columns to standard names
    rename_map = {
        'Organization': 'Committee',
        'Eva': 'Eval',
        'Year_1': 'Sort Year',  # Second Year column is sort year
    }
    df = df.rename(columns=rename_map)

    # If 'Sort Year' doesn't exist but we have numeric year data, create it
    if 'Sort Year' not in df.columns and 'Year' in df.columns:
        import re
        def extract_sort_year(year_str):
            if pd.isna(year_str):
                return None
            match = re.search(r'(\d{4})', str(year_str))
            return int(match.group(1)) if match else None
        df['Sort Year'] = df['Year'].apply(extract_sort_year)

    self.df = df
    df = Table.table_clean_df(self)

    # Consolidate year ranges if requested
    if self.consolidate:
        df = consolidate_years(df)

    # Use 'Sort Year' if available, otherwise fall back to 'Year'
    if sort_by in df.columns:
        df = df.sort_values(by=[sort_by], ascending=[self.ascending])
    elif 'Year' in df.columns:
        df = df.sort_values(by=['Year'], ascending=[self.ascending])

    return df


def consolidate_years(df):
    """
    Consolidate rows with the same Role and Committee into single entries
    with combined year ranges.
    """
    import re

    def parse_year_range(year_str):
        """Parse '2024 - 2025' into (2024, 2025) or '2024' into (2024, 2024)"""
        if pd.isna(year_str) or year_str == '':
            return None, None
        year_str = str(year_str).strip()
        match = re.match(r'(\d{4})\s*-\s*(\d{4})?', year_str)
        if match:
            start = int(match.group(1))
            end = int(match.group(2)) if match.group(2) else start
            return start, end
        # Try single year
        match = re.match(r'(\d{4})', year_str)
        if match:
            year = int(match.group(1))
            return year, year
        return None, None

    # Parse years and add columns
    df = df.copy()
    df['_start_year'] = df['Year'].apply(lambda x: parse_year_range(x)[0])
    df['_end_year'] = df['Year'].apply(lambda x: parse_year_range(x)[1])

    # Drop rows with unparseable years
    df = df.dropna(subset=['_start_year'])

    # Determine grouping columns (use Committee if exists, otherwise Organization)
    group_col = 'Committee' if 'Committee' in df.columns else 'Organization'
    if group_col not in df.columns:
        # If neither exists, just return df sorted
        return df

    # Group by Role and Committee/Organization, find min start and max end
    agg_dict = {
        '_start_year': 'min',
        '_end_year': 'max',
    }
    if 'Type' in df.columns:
        agg_dict['Type'] = 'first'
    if 'Eval' in df.columns:
        agg_dict['Eval'] = 'first'
    if 'Sort Year' in df.columns:
        agg_dict['Sort Year'] = 'max'

    grouped = df.groupby(['Role', group_col], as_index=False).agg(agg_dict)

    # Rename back to Committee for consistency
    if group_col != 'Committee':
        grouped = grouped.rename(columns={group_col: 'Committee'})

    # Create consolidated Year string
    def make_year_range(row):
        start = int(row['_start_year'])
        end = int(row['_end_year'])
        if start == end:
            return str(start)
        else:
            return f"{start} - {end}"

    grouped['Year'] = grouped.apply(make_year_range, axis=1)

    # Clean up temp columns
    grouped = grouped.drop(columns=['_start_year', '_end_year'])

    return grouped
